using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Networking;
using CatCafePreview.Standalone;
namespace CatCafePreview {
 public sealed class StandaloneReservationConversationSmoke:MonoBehaviour {
  static int checks;static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("Reservation ADV: "+label);}
  static CafeResponse Send(LocalCafeBackend b,string kind,string choice=null,int slot=1,string id=null,string[] working=null){var s=b.Simulation.State;CafeResponse r=null;var call=b.Request("/commands",JsonUtility.ToJson(new PythonShiftCommand{request_id=Guid.NewGuid().ToString("N"),instance_id=s.instance_id,expected_revision=s.revision,kind=kind,choice=choice,event_id=id??CafeReservationDialogue.EventId(s.reservation),save_slot=slot,save_id=slot.ToString(),working_cats=working??new string[0]}),v=>r=v);while(call.MoveNext()){}return r;}
  static void Good(LocalCafeBackend b,string kind,string choice=null,int slot=1,string[] working=null){var r=Send(b,kind,choice,slot,working:working);Check(r.result==UnityWebRequest.Result.Success,kind+": "+r.error);}
  public static CafeRules Rules(string branch="success") {var r=JsonUtility.FromJson<CafeRules>(Resources.Load<TextAsset>("CatCafeStandalone/rules").text);r.starting_funds=30000;r.starting_popularity=30;r.goal_stages[0].target=r.goal_stages[1].target=r.goal_stages[2].target=1;r.intake.day=r.regular_introduction.day=9999;r.growth.threshold=10000;r.store_events.probability=0;r.reservation.open_up_count=branch=="failure"?999:0;r.reservation.arrival_tick=0;r.arrival_ticks=new[]{5,10};foreach(var c in r.cats)c.features=branch=="mismatch"?c.features.Where(x=>x!=r.reservation.feature).ToArray():c.features.Concat(new[]{r.reservation.feature}).Distinct().ToArray();return r;}
  public static void Setup(LocalCafeBackend b){Good(b,"new_game","popularity");Good(b,"day_off");Good(b,"continue_goal");Good(b,"advance_goal");Good(b,"day_off");Check(b.Simulation.ReservationWaiting && b.Simulation.State.day==3,"offer day");b.PrepareReservationConversation();}
  public static void Finish(LocalCafeBackend b){foreach(var r in b.ReservationConversations)while(r.Current!=null && !r.Current.completed && r.Current.branch_id!="introduction"){r.Current.node=3;r.Current.page_offset=0;CafeReservationDialogue.Finish(r);}b.ReservationConversationOpen=false;b.RememberViewedConversations();}
  static string Facts(LocalCafeBackend b){var s=JsonUtility.FromJson<CafeSnapshot>(JsonUtility.ToJson(b.Simulation.State));s.instance_id="";s.revision=0;s.NormalizeJsonStrings();return JsonUtility.ToJson(s);}
  static void Legacy(LocalCafeBackend b,string folder,string status){Good(b,"save_game",slot:6);var old=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(folder,"slot-6.json")));old.reservation_conversations=null;old.reservation_conversation_selected=null;File.WriteAllText(Path.Combine(folder,"slot-6.json"),JsonUtility.ToJson(old));var fresh=new LocalCafeBackend(folder,b.Simulation.Rules);Good(fresh,"load_game",slot:6);var rows=fresh.ReservationConversations;Check(status=="waiting"?rows.Length==1 && rows[0].response.branch_id=="introduction":status=="accepted"?rows.Length==1 && rows[0].response==null:rows.Length==0,"legacy "+status);Check(!rows.Any(r=>r.response?.completed==true || r.result?.completed==true),"legacy invented read history");}
  public static int Run(string root){checks=0;Directory.CreateDirectory(root);
   foreach(string branch in new[]{"decline","success","failure","unserved","mismatch"}){string outcome=branch=="mismatch"?"failure":branch;
    string folder=Path.Combine(root,branch);var b=new LocalCafeBackend(folder,Rules(branch));Setup(b);var row=b.ReservationConversation;Check(row.event_id=="reservation-3" && row.visit_day==4 && row.open_up_count==b.Simulation.Rules.reservation.open_up_count,"saved config");Check(b.Simulation.State.reservation.result==null && row.result==null,"early ending");Check(CafeReplayCatalog.FromSave(new CafeSaveEnvelope{state=b.Simulation.State,reservation_conversations=b.ReservationConversations},b.Simulation.Rules,id=>b.Simulation.Definition(id).name,b.Details.CustomerName,b.Details.ContentId).Length==0,"unread unlocked Extra");row.Current.node=1;row.Current.page_offset=2;Good(b,"save_game",slot:2);var fresh=new LocalCafeBackend(folder,Rules(branch));Good(fresh,"load_game",slot:2);Check(fresh.ReservationConversation.Current.node==1 && fresh.ReservationConversation.Current.page_offset==2,"intro restart");Legacy(b,folder,"waiting");
    Check(Send(b,"resolve_reservation","accept",id:"wrong").result!=UnityWebRequest.Result.Success,"wrong ID accepted");string before=Facts(b);Check(Send(b,"day_off").result!=UnityWebRequest.Result.Success && Facts(b)==before,"unanswered advances");double funds=b.Simulation.State.funds,pop=b.Simulation.State.popularity;Good(b,"resolve_reservation",branch=="decline"?"decline":"accept");Check(b.Simulation.State.funds==funds && b.Simulation.State.popularity==pop && b.ReservationResultPending,"answer changed rewards");before=Facts(b);Check(Send(b,"resolve_reservation","accept").result!=UnityWebRequest.Result.Success && Facts(b)==before,"answer duplicate");row=b.ReservationConversation;row.Current.node=1;Good(b,"save_game",slot:3);fresh=new LocalCafeBackend(folder,Rules(branch));Good(fresh,"load_game",slot:3);Check(fresh.ReservationConversation.Current.node==1 && fresh.ReservationResultPending,"answer restart");Check(Send(b,"day_off").result!=UnityWebRequest.Result.Success && b.ConversationProgressReason.Contains("特別予約"),"hidden answer no reason");Finish(b);Check(!b.ReservationBlocksProgress,"answered blocks waiting days");Legacy(b,folder,branch=="decline"?"declined":"accepted");
    if(branch=="decline"){Good(b,"continue_goal");Good(b,"day_off");Check(b.Simulation.State.day==4,"declined day progression");continue;}
    Good(b,"continue_goal");Good(b,"day_off");Check(b.Simulation.ReservationVisitToday && !b.View().day_off.can_select,"visit day rest allowed");Check(Send(b,"day_off").result!=UnityWebRequest.Result.Success,"rest command allowed");if(branch=="success")Good(b,"advance_goal");Good(b,"set_shifts",working:branch=="unserved"?new string[0]:b.Simulation.State.cats.Select(c=>c.id).ToArray());Good(b,"start_business");int guard=0;while(b.Simulation.State.phase=="open" && guard++<100){Check(!b.ReservationBlocksProgress,"result stops other seats");Good(b,"advance_business");}
    Check(b.Simulation.State.phase=="closed","closing lost");if(branch=="success")Check(b.PopularityEndingPending && b.ReservationResultPending,"simultaneous goal result absent");Check(b.Simulation.State.exchanges.Count==0 && b.Simulation.State.visits.Count>1,"other seats/closing lost");Check(b.Simulation.State.reservation.result==(branch=="unserved"?null:outcome),"service result differs: "+branch+" actual="+b.Simulation.State.reservation.result);if(branch=="unserved")Good(b,"next_day");Check(b.ReservationResultPending && b.ReservationSafe && b.ReservationConversation.result.branch_id==outcome,"result not queued");Check(b.ReservationConversation.result.node==0,"result auto read");Good(b,"save_game",slot:4);fresh=new LocalCafeBackend(folder,Rules(branch));Good(fresh,"load_game",slot:4);Check(fresh.ReservationResultPending,"result restart");before=Facts(b);Finish(b);Check(before==Facts(b) && !b.ReservationResultPending,"read repeated rewards");Good(b,"save_game",slot:5);var bad=JsonUtility.FromJson<CafeSaveEnvelope>(File.ReadAllText(Path.Combine(folder,"slot-5.json")));bad.slot=8;bad.reservation_conversations[0].result.branch_id="forged";File.WriteAllText(Path.Combine(folder,"slot-8.json"),JsonUtility.ToJson(bad));before=Facts(b);Check(Send(b,"load_game",slot:8).result!=UnityWebRequest.Result.Success && before==Facts(b),"invalid progress replaced game");Legacy(b,folder,"resolved");var entries=b.Replays.Load().entries;Check(entries.Any(e=>e.conversation_id==CafeReservationDialogue.Id+".result" && e.branch_id==outcome),"Extra missing branch");CafeReplayCatalog.Validate(b.Replays.Load());
   }return checks;
  }
  string output;LocalCafeBackend backend;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--catcafe-reservation-adv-check");if(i<0)return;var q=new GameObject("Reservation ADV QA").AddComponent<StandaloneReservationConversationSmoke>();DontDestroyOnLoad(q);q.output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(q.output);Application.runInBackground=true;q.StartCoroutine(q.Guard());}
  System.Collections.IEnumerator Guard(){var run=Player();while(true){bool next;try{next=run.MoveNext();}catch(Exception ex){File.WriteAllText(Path.Combine(output,"failure.txt"),ex.ToString());Debug.LogException(ex);yield break;}if(!next)yield break;yield return run.Current;}}
  void Apply(PythonStateClient c){typeof(PythonStateClient).GetMethod("Accept",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(c,new object[]{backend.View()});}
  System.Collections.IEnumerator Player(){yield return new WaitForSecondsRealtime(1);int n=Run(Path.Combine(output,"backend"));backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules());bool restart=Environment.GetCommandLineArgs().Contains("--reservation-resume");if(restart)Good(backend,"load_game",slot:9);else {Setup(backend);Good(backend,"save_game",slot:2);}CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);var c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;var ui=c.GetComponent<ReservationConversationPanel>();var owner=c.GetComponent<PythonReservationPanel>();Check(ui!=null && ui.Showing,"ADV UI absent");var browser=c.GetComponent<PythonSaveBrowser>();browser.OpenLoad();yield return null;Check(browser.panel.activeInHierarchy && !c.GetComponent<PythonGoalPanel>().panel.activeSelf,"goal covers load browser");browser.Close();yield return null;if(!restart){backend.ReservationConversation.Current.node=3;backend.ReservationConversation.Current.page_offset=0;Apply(c);yield return null;string before=Facts(backend);ui.Answer(true);yield return null;Check(owner.Confirming && owner.confirmation.activeInHierarchy,"accept confirmation absent");owner.Cancel();yield return null;Check(!owner.Confirming && before==Facts(backend),"cancel changed state");ui.Answer(false);yield return null;Check(owner.Confirming,"decline confirmation absent");owner.Cancel();yield return null;ui.Answer(true);yield return null;owner.Confirm();owner.Confirm();yield return new WaitForSecondsRealtime(1);Check(backend.ReservationConversation.response.branch_id=="accept","UI answer absent");ui.Close();c.GetComponent<PythonEventListPanel>().ShowMenu(8);yield return null;Check(ui.Showing,"list resume");backend.ReservationConversation.Current.node=1;Good(backend,"save_game",slot:9);}
   else Check(backend.ReservationConversation.Current.node==1,"process restart position");
   if(!restart){
    backend=new LocalCafeBackend(Path.Combine(output,"backend/success"),Rules());Good(backend,"load_game",slot:4);CafeBackends.UseLocal(backend);Apply(c);yield return null;ui=c.GetComponent<ReservationConversationPanel>();Check(ui.Showing && backend.ReservationConversation.result.branch_id=="success" && c.GetComponent<PopularityEndingPanel>()?.Showing!=true,"result UI absent or ending covers it");
    var growth=backend.View();growth.growth_choices=new[]{new PythonGrowthChoice()};c.GetComponent<PythonGrowthPanel>().Apply(growth);Check(!c.GetComponent<PythonGrowthPanel>().panel.activeSelf,"growth covers result");
    ui.Close();c.GetComponent<PythonEventListPanel>().ShowMenu(8);yield return null;Check(ui.Showing && c.GetComponent<PythonEventListPanel>().PendingFor(8)==1,"result list resume");
    string state=Facts(backend);backend.ReservationConversation.result.node=3;Apply(c);yield return null;ui.Next();yield return null;Check(!backend.ReservationResultPending && Facts(backend)==state && c.GetComponent<PopularityEndingPanel>().Showing,"UI result duplicated rewards or goal not resumed");
    UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafeTitle");yield return new WaitForSecondsRealtime(2);var extra=FindObjectOfType<PythonTitleScreen>().GetComponent<TitleExtraPanel>();foreach(string branch in new[]{"decline","success","failure","unserved"})backend.Replays.Merge(new LocalCafeBackend(Path.Combine(output,"backend/"+branch),Rules(branch)).Replays.Load().entries);extra.Open();yield return null;state=Facts(backend);string meta=JsonUtility.ToJson(backend.ReservationConversation);
    foreach(string branch in new[]{"response/accept","response/decline","result/success","result/failure","result/unserved"}){extra.OpenReplay(CafeReservationDialogue.Id+"."+branch);yield return null;Check(extra.Replay.Showing,"Extra UI absent: "+branch);extra.Replay.Answer(true);extra.Replay.Next();extra.Replay.Close();}Check(state==Facts(backend) && meta==JsonUtility.ToJson(backend.ReservationConversation),"Extra changed gameplay or progress");extra.Hide();
    backend=new LocalCafeBackend(Path.Combine(output,"manual"),Rules());Good(backend,"load_game",slot:9);CafeBackends.UseLocal(backend);UnityEngine.SceneManagement.SceneManager.LoadScene("CatCafePythonState");yield return new WaitForSecondsRealtime(2);c=FindObjectOfType<PythonStateClient>();Apply(c);yield return null;
   }
   Screen.SetResolution(restart?1024:1280,restart?768:800,false);Apply(c);File.WriteAllText(Path.Combine(output,restart?"restart-result.txt":"result.txt"),"PASS: "+checks+"; backend="+n);ScreenCapture.CaptureScreenshot(Path.Combine(output,restart?"restart.png":"manual-ready.png"));
  }
 }
}
